import{_ as p,a0 as o,w as l,s as d,I as a,x as e,a1 as i,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"在 OBS 中将摄像头锁定到特定的 USB 端口 | LCTT x X-CMD","titleTemplate":false,"description":"在 OBS 中将摄像头锁定到特定的 USB 端口 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 OBS 中将摄像头锁定到特定的 USB 端口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 OBS 中将摄像头锁定到特定的 USB 端口 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20220107 Lock your camera to a specific USB port in OBS","title":"在 OBS 中将摄像头锁定到特定的 USB 端口","tag":"202305","desc":""},"relativePath":"202305/20220107 Lock your camera to a specific USB port in OBS.md","filePath":"[post].md"}'),u={name:"202305/20220107 Lock your camera to a specific USB port in OBS.md"};function c(h,s,b,g,v,m){const n=o("Link");return l(),d("div",null,[s[18]||(s[18]=a("h1",{id:"在-obs-中将摄像头锁定到特定的-usb-端口",tabindex:"-1"},[e("在 OBS 中将摄像头锁定到特定的 USB 端口 "),a("a",{class:"header-anchor",href:"#在-obs-中将摄像头锁定到特定的-usb-端口","aria-label":"Permalink to “在 OBS 中将摄像头锁定到特定的 USB 端口”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"为了使复杂的摄像头设置标准化，你可以对 Linux 文件系统中摄像头的位置分配施加一些特殊规则。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/06/233102xqfzerq9mek1e9mt.png",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("如果在 Linux 上用多个摄像头 ",-1)),i(n,{href:"https://opensource.com/life/15/12/real-time-linux-video-editing-with-obs-studio"},{default:t(()=>[...s[0]||(s[0]=[e("使用 OBS 进行直播",-1)])]),_:1}),s[2]||(s[2]=e("，你可能会注意到摄像头会在开机时按照它们被检测到的顺序加载。通常情况下你不需要特别在意，但如果你有一个固定的直播设置和复杂的 OBS 模板，你需要知道现实世界中哪个摄像头将会显示在虚拟世界的哪个屏幕上。换句话说，你不希望今天将一个设备分配为“摄像头 A”，而明天它却成为“摄像头 B”。",-1))]),s[21]||(s[21]=r(`<p>为了使复杂的摄像头设置标准化，你可以对 Linux 文件系统中摄像头的位置分配施加一些特殊规则。</p><h3 id="udev-子系统" tabindex="-1">udev 子系统 <a class="header-anchor" href="#udev-子系统" aria-label="Permalink to “udev 子系统”">​</a></h3><p>在 Linux 上处理硬件外设的系统称为 udev。它检测和管理你接入计算机的所有设备。你可能没有意识到它的存在，因为它不会吸引太多注意力。尽管当你插入 USB 闪存驱动器以在桌面上打开它或连接打印机时，你肯定与它交互过。</p><h3 id="硬件检测" tabindex="-1">硬件检测 <a class="header-anchor" href="#硬件检测" aria-label="Permalink to “硬件检测”">​</a></h3><p>假设你有两个 USB 摄像头：一个在电脑左侧，另一个在右侧。左侧摄像头拍摄近景，右侧摄像头拍摄远景，并且在直播过程中你需要切换两个摄像头。在 OBS 中，你将每个摄像头添加到 <ruby>源<rt>Sources</rt></ruby> 面板中，并直观地将它们命名为 “camLEFT” 和 “camRIGHT”。</p><p>设想一种最坏的场景，你有两个 <em>相同的</em> 摄像头：它们是同一品牌、同一型号。这是最坏的情况，因为当两个硬件设备完全相同时，它们几乎不可能有任何独特的 ID，以便你的电脑能够将它们区分开来。</p><p>不过，这个难题有解决办法，只需要一些简单的终端命令进行一些调查。</p><h4 id="_1、获取厂商和产品-id" tabindex="-1">1、获取厂商和产品 ID <a class="header-anchor" href="#_1、获取厂商和产品-id" aria-label="Permalink to “1、获取厂商和产品 ID”">​</a></h4><p>首先，将一个摄像头插入你想要它分配到的 USB 端口。然后输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 006 Device 002: ID 0951:1666 Kingston Technology DataTraveler G4</span></span>
<span class="line"><span>Bus 005 Device 003: ID 03f0:3817 Hewlett-Packard LaserJet P2015 series</span></span>
<span class="line"><span>Bus 003 Device 006: ID 045e:0779 Microsoft Corp. LifeCam HD-3000</span></span>
<span class="line"><span>Bus 003 Device 002: ID 8087:0025 Intel Corp. </span></span>
<span class="line"><span>Bus 002 Device 001: ID 1d6b:0003 Linux Foundation 3.0 root hub</span></span>
<span class="line"><span>Bus 001 Device 003: ID 046d:c216 Logitech, Inc. Dual Action Gamepad</span></span>
<span class="line"><span>Bus 001 Device 002: ID 048d:5702 Integrated Technology Express, Inc. </span></span>
<span class="line"><span>Bus 001 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>你通常可以专门搜索字符串 <code>cam</code> 以缩小结果范围，因为大多数（但不是所有）摄像头都会报告为 “camera”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb | grep -i cam</span></span>
<span class="line"><span>Bus 003 Device 006: ID 045e:0779 Microsoft Corp. LifeCam HD-3000</span></span></code></pre></div><p>这里有很多信息。ID 被列为 <code>045e:0779</code>。第一个数字是供应商 ID，第二个数字是产品 ID。把它们写下来，因为稍后你会需要它们。</p><h4 id="_2、获取-usb-标识符" tabindex="-1">2、获取 USB 标识符 <a class="header-anchor" href="#_2、获取-usb-标识符" aria-label="Permalink to “2、获取 USB 标识符”">​</a></h4><p>你还获取了摄像头的设备路径：总线 3，设备 6。在 Linux 中有一句话：“一切皆文件”，实际上，USB 设备被描述为以 <code>/dev/bus/usb/</code> 开始，以总线（本例中为 003）和设备（本例中为 006）结尾的文件路径。查看 <code>lsusb</code> 输出中的总线和设备号。它们告诉你该摄像头位于 <code>/dev/bus/usb/003/006</code>。</p><p>你可以使用 <code>udevadm</code> 命令获取此 USB 设备的内核代号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo udevadm info --attribute-walk /dev/bus/usb/003/006 | grep &quot;KERNEL=&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   KERNEL==&quot;3-6.2.1&quot;</span></span></code></pre></div><p>这个例子中的内核 USB 标识符是 <code>3-6.2.1</code>。把你系统中的标识符记下来，因为之后也会用到它。</p><h4 id="_3、为每个摄像头重复该过程" tabindex="-1">3、为每个摄像头重复该过程 <a class="header-anchor" href="#_3、为每个摄像头重复该过程" aria-label="Permalink to “3、为每个摄像头重复该过程”">​</a></h4><p>将另一个摄像头（如果你有多个摄像头，则为每个摄像头）连接到要分配给它的 USB 端口。这与你用于另一个摄像头的 USB 端口是不同的！</p><p>重复该过程，获取供应商和产品 ID（如果摄像头是相同的品牌和型号，则应与第一个摄像头相同）以及内核 USB 标识符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb | grep -i cam</span></span>
<span class="line"><span>Bus 001 Device 004: ID 045e:0779 Microsoft Corp. LifeCam HD-3000</span></span>
<span class="line"><span>$ sudo udevadm info --attribute-walk dev/bus/usb/001/004 | grep &quot;KERNEL=&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   KERNEL==&quot;1-6&quot;</span></span></code></pre></div><p>在这个例子中，我已经确定我的摄像头连接到了 1-6 和 3-6.2.1（第一个是我的机器上的 USB 端口，另一个是插在我的机器上的显示器插口的集线器，这就是为什么一个比另一个更复杂的原因）。</p><h3 id="编写一个-udev-规则" tabindex="-1">编写一个 udev 规则 <a class="header-anchor" href="#编写一个-udev-规则" aria-label="Permalink to “编写一个 udev 规则”">​</a></h3><p>你已经有了所需的一切，因此现在可以编写一个规则，告诉 udev 在特定的 USB 端口找到一个摄像头时给它一个一致的标识符。</p><p>创建并打开一个名为 <code>/etc/udev/rules.d/50-camera.conf</code> 的文件，并输入这两个规则，使用适合你自己系统的厂商和产品 ID 和内核标识符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SUBSYSTEM==&quot;usb&quot;, KERNEL==&quot;1-6&quot;, ATTR{idVendor}==&quot;045e&quot;, ATTR{idProduct}==&quot;0779&quot;, SYMLINK+=&quot;video100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SUBSYSTEM==&quot;usb&quot;, KERNEL==&quot;3-6.2.1&quot;, ATTR{idVendor}==&quot;045e&quot;, ATTR{idProduct}==&quot;0779&quot;, SYMLINK+=&quot;video101&quot;</span></span></code></pre></div><p>这些规则告诉 udev，当在特定的 USB 位置找到与特定供应商和产品 ID 匹配的设备时，创建一个名为 <code>video100</code> 和 <code>video101</code> 的符号链接（有时也称为“别名”）。符号链接大多是任意的。我使用较大的数字，这样它们就容易被发现，并且数字不能与现有设备冲突。如果实际上有超过 101 个摄像头连接到计算机上，请使用 <code>video200</code> 和 <code>video201</code> 以确保安全（记得联系我！我很想了解 <em>该</em> 项目的情况）。</p><h3 id="重启" tabindex="-1">重启 <a class="header-anchor" href="#重启" aria-label="Permalink to “重启”">​</a></h3><p>重新启动计算机。你现在可以让摄像头保持连接在计算机上，但实际上这并不重要。一旦 udev 加载了规则，它就会遵循这些规则，无论设备是否在启动期间附加或稍后插入。</p><p>许多人说 Linux 从不需要重启，但是 udev 在引导期间加载其规则，而且此外，你想保证你的 udev 规则在重新启动时也起作用。</p><p>计算机重新启动后，请查看摄像头注册的 <code>/dev/video</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 /dev/video*</span></span>
<span class="line"><span>/dev/video0</span></span>
<span class="line"><span>/dev/video1</span></span>
<span class="line"><span>/dev/video100</span></span>
<span class="line"><span>/dev/video101</span></span>
<span class="line"><span>/dev/video2</span></span>
<span class="line"><span>/dev/video3</span></span></code></pre></div><p>正如你所看到的，在 <code>video100</code> 和 <code>video101</code> 有条目。今天，这些是指向 <code>/dev/video2</code> 和 <code>/dev/video3</code> 的符号链接，但明天它们可能是指向 <code>/dev/video1</code> 和 <code>/dev/video2</code> 或任何其他基于 Linux 检测和分配文件的组合。</p><p><img src="https://opensource.com/sites/default/files/uploads/obs-udev.jpg" alt="两个摄像头角度" title="Two camera angles"></p><p>你可以在 OBS 中使用这些符号链接，这样 camLEFT 始终是 camLEFT，camRIGHT 始终是 camRIGHT。</p><p><em>（题图：MJ/9bb70b6d-9f49-493a-8daf-5546d207781f）</em></p><hr>`,38)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/22/1/cameras-usb-ports-obs"},{default:t(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/22/1/cameras-usb-ports-obs",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[5]||(s[5]=[e("Seth Kenlon",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),i(n,{href:"https://github.com/hanszhao80"},{default:t(()=>[...s[7]||(s[7]=[e("hanszhao80",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const S=p(u,[["render",c]]);export{B as __pageData,S as default};
